let language = "zh-CN";
try {
  if (localStorage.getItem("ricochet.language") === "en") language = "en";
} catch {}
export const getLanguage = () => language;
export function setLanguage(value) {
  language = value === "en" ? "en" : "zh-CN";
  try {
    localStorage.setItem("ricochet.language", language);
  } catch {}
}
export function t(key) {
  return dictionaries[language][key] ?? dictionaries["zh-CN"][key] ?? key;
}
export const teamName = (owner) => t(owner === 1 ? "Red" : "Blue");
